    public function values(Type $type): ?array
    {
        $finiteTypes = $type->getFiniteTypes();
        if ($finiteTypes === [] || count($finiteTypes) > self::MAX_VARIANTS) {
            return null;
        }

        return $finiteTypes;
    }
}
